<template>
<main class="site-main home-page"><div class="page-shell">
<section class="hero-panel"><div class="hero-copy"><div class="hero-kicker"><i class="bi bi-stars"></i> CAVXX · VIDEO</div><h1>发现今天值得看的影片</h1><p>最新更新、热门影片与精选内容，一站式快速浏览。</p><div class="hero-actions"><button class="hero-primary" @click="scrollTo('latest')"><i class="bi bi-play-fill"></i> 浏览最新</button><button class="hero-secondary" @click="scrollTo('hot')"><i class="bi bi-fire"></i> 查看热门</button></div></div><div class="hero-orbit"><span class="orbit-ring"></span><i class="bi bi-play-fill"></i></div></section>
<section class="quick-nav"><button class="quick-item active" @click="scrollTo('latest')"><i class="bi bi-lightning-charge-fill"></i> 最新</button><button class="quick-item" @click="scrollTo('hot')"><i class="bi bi-fire"></i> 热门</button><button class="quick-item" @click="scrollTo('day-hot')"><i class="bi bi-bar-chart-fill"></i> 今日热门</button><button class="quick-item" @click="scrollTo('featured')"><i class="bi bi-stars"></i> 高分精选</button></section>
<section id="featured" v-if="featured.length" class="featured-section"><div class="section-bar"><div><div class="section-kicker">TOP RATED</div><h2 class="section-heading">高分精选</h2><div class="section-subtitle">精选内容</div></div></div><div class="featured-grid"><router-link v-for="(v,i) in featured" :key="v.vod_id" :to="`/play/${v.vod_id}`" class="featured-card"><img :src="v.vod_pic||'/fallback.svg'" :alt="v.vod_name" loading="lazy"><div class="featured-overlay"></div><span class="featured-rank">0{{i+1}}</span><div class="featured-content"><span class="featured-tag">{{v.type_name||'精选'}}</span><strong>{{v.vod_name}}</strong><small><i class="bi bi-star-fill"></i> {{v.vod_score||'暂无评分'}} · {{v.vod_hits||0}} 次播放</small></div></router-link></div></section>
<section id="latest" class="content-section video-section"><div class="section-bar"><div><div class="section-kicker">LATEST</div><h2 class="section-heading">最新影片</h2><div class="section-subtitle">持续更新</div></div></div><div class="video-grid"><template v-if="loading"><VideoCardSkeleton v-for="i in 6" :key="i"/></template><VideoCard v-else v-for="v in latest" :key="v.vod_id" :item="v"/></div></section>
<section id="hot" class="content-section video-section"><div class="section-bar"><div><div class="section-kicker">MOST VIEWED</div><h2 class="section-heading">热门影片</h2><div class="section-subtitle">人气内容</div></div></div><div class="video-grid"><template v-if="loading"><VideoCardSkeleton v-for="i in 6" :key="i"/></template><VideoCard v-else v-for="v in hot" :key="v.vod_id" :item="v"/></div></section>
<VideoSection id="day-hot" title="今日热门" kicker="TODAY'S HOT" subtitle="热门推荐" :list="day" :loading="loading"/>
<section class="all-latest"><div class="section-bar"><div><div class="section-kicker">BROWSE ALL</div><h2 class="section-heading">更多最新影片</h2><div class="section-subtitle">第 {{page}} 页 · 共 {{total}} 页</div></div></div><div class="video-grid"><template v-if="loading"><VideoCardSkeleton v-for="i in 10" :key="i"/></template><VideoCard v-else v-for="v in all" :key="v.vod_id" :item="v"/></div><div v-if="!loading&&!all.length" class="empty-state"><i class="bi bi-inbox"></i><strong>暂时没有内容</strong></div><Pagination :page="page" :total="total" @change="changePage"/></section>
</div></main></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {getLatestVideos,getHotVideos,getDayHotVideos,getTopVideos} from '../api/cms'
import VideoCard from '../components/VideoCard.vue'
import VideoCardSkeleton from '../components/VideoCardSkeleton.vue'
import Pagination from '../components/Pagination.vue'
const route=useRoute(),router=useRouter(),latest=ref([]),hot=ref([]),day=ref([]),top=ref([]),all=ref([]),loading=ref(false),page=ref(1),total=ref(1),featured=computed(()=>top.value.slice(0,3))

function scrollTo(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth'})}
async function load(){page.value=Math.max(1,Number(route.query.page||1));loading.value=true;const r=await Promise.allSettled([getLatestVideos(1,12),getHotVideos(1,12),getDayHotVideos(1,12),getTopVideos(1,12),getLatestVideos(page.value,20)]);latest.value=r[0].status==='fulfilled'?r[0].value.data.list||[]:[];hot.value=r[1].status==='fulfilled'?r[1].value.data.list||[]:[];day.value=r[2].status==='fulfilled'?r[2].value.data.list||[]:[];top.value=r[3].status==='fulfilled'?r[3].value.data.list||[]:[];all.value=r[4].status==='fulfilled'?r[4].value.data.list||[]:[];total.value=r[4].status==='fulfilled'?Number(r[4].value.data.pagecount||1):1;loading.value=false;document.title='CAVXX - 最新影片'}
function changePage(p){router.push({name:'home',query:p>1?{page:String(p)}:{}})}
watch(()=>route.fullPath,load,{immediate:true})
</script>
<style scoped>
.hero-panel{position:relative;display:flex;align-items:center;justify-content:space-between;min-height:250px;margin:20px 0 18px;padding:42px 48px;overflow:hidden;border:1px solid #ffffff12;border-radius:20px;background:radial-gradient(circle at 82% 40%,#ff4d7326,transparent 28%),linear-gradient(120deg,#171720,#111117)}.hero-copy{position:relative;z-index:2;max-width:620px}.hero-kicker{color:#ff6b8d;font-size:9px;font-weight:800;letter-spacing:.16em}.hero-copy h1{margin:12px 0 10px;color:#fff;font-size:clamp(28px,4vw,44px);font-weight:850}.hero-copy p{margin:0 0 24px;color:#92929d;font-size:14px}.hero-actions{display:flex;gap:10px}.hero-primary,.hero-secondary{min-height:42px;padding:0 18px;border-radius:10px;font-size:13px;font-weight:700}.hero-primary{border:0;background:#ff4d73;color:#fff}.hero-secondary{border:1px solid #ffffff1c;background:#ffffff08;color:#ddd}.hero-orbit{position:relative;width:210px;height:180px;display:grid;place-items:center;color:#ff7894;font-size:54px}.orbit-ring{position:absolute;width:170px;height:170px;border:1px solid #ff78942e;border-radius:50%;box-shadow:0 0 60px #ff4d7318}.all-latest{margin-top:30px}.section-count{color:#777}@media(max-width:900px){.video-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:640px){.hero-panel{min-height:0;margin:12px 0;padding:28px 20px}.hero-copy h1{font-size:28px}.hero-orbit{display:none}.hero-actions{flex-wrap:wrap}.video-grid{grid-template-columns:1fr}.featured-grid{grid-template-columns:1fr}.featured-card,.featured-card:first-child{min-height:220px;grid-column:auto}}
</style>
